arguments.command:
cd /workspace && python3 - <<'EOF'
import json
for n in ('E0','E8','E30'):
    d=json.load(open(f'evidence/evaluation/{n}.json'))
    print('='*20,n,'='*20)
    for k,v in d.items():
        if isinstance(v,(list,dict)):
            print(f'{k}: {type(v).__name__} len={len(v)}')
        else:
            print(f'{k}: {v!r}')
EOF

