arguments.command:
cd /workspace && python3 - <<'EOF'
import pandas as pd, json, glob, re, sys
sys.path.insert(0,'qat/vendor/verl')
from verl.utils.reward_score.math_dapo import last_boxed_only_string, remove_boxed, normalize_final_answer, is_correct_minerva
d=pd.read_parquet('data/skywork_or1_7b_math_difficulty1-15_16k.parquet')
lookup={}
for i,r in d.iterrows(): lookup.setdefault(r['prompt'][-1]['content'],[]).append(i)
def gts_of(prompt):
    m=re.search(r'<｜User｜>(.*?)<｜Assistant｜>', prompt, re.S); body=m.group(1) if m else prompt
    return [json.loads(d.iloc[i]['reward_model']['ground_truth']) for i in lookup.get(body,[])]
def boxed_ok(out,gts):
    s=out[-300:]; b=last_boxed_only_string(s)
    if not b: return False
    p=normalize_final_answer(remove_boxed(b))
    return any(p==normalize_final_answer(a) for sub in gts for a in sub)
def minerva_ok(out,gts):
    s=out[-300:]
    return any(is_correct_minerva(s,a)[0] for sub in gts for a in sub)
for f in sorted(glob.glob('evidence/training/*/rollouts/*.jsonl')):
    rows=[json.loads(l) for l in open(f)]
    cur=sum(r['score']>0 for r in rows)
    mn=sum(minerva_ok(r['output'],gts_of(r['prompt'])) for r in rows)
    bx=sum(boxed_ok(r['output'],gts_of(r['prompt'])) for r in rows)
    print(f.split('/')[-1], 'dump_acc',cur,'minerva',mn,'boxed',bx)
EOF

