lookup={}
for i,r in d.iterrows(): lookup.setdefault(r['prompt'][-1]['content'],[]).append(i)
def gts_of(prompt):
    m=re.search(r'<｜User｜>(.*?)<｜Assistant｜>', prompt, re.S); body=m.group(1) if m else prompt
    return [json.loads(d.iloc[i]['reward_model']['ground_truth']) for i in lookup.get(body,[])]
def ok_equiv(out,gts):
    return any(mr_score(out,a)>0 for sub in gts for a in sub)
def ok_norm(out,gts):
    b=last_boxed_only_string(out[-300:])
    if not b: return False
    p=normalize_final_answer(remove_boxed(b))
    return any(p==normalize_final_answer(a) for sub in gts for a in sub)
